1	// Package apitest builds a whole Tally service for tests: the store, a fake clock, the fake payment gateway, an email
2	// outbox, fake webhook receivers and DNS, the services and the API server, with two organizations to start from.
3	package apitest
4	
5	import (
6		"bytes"
7		"context"
8		"encoding/json"
9		"fmt"
10		"io"
11		"net"
12		"net/http"
13		"net/http/httptest"
14		"strings"
15		"sync"
16		"testing"
17		"time"
18	
19		"example.com/tally/internal/api"
20		"example.com/tally/internal/clock"
21		"example.com/tally/internal/mail"
22		"example.com/tally/internal/payments"
23		"example.com/tally/internal/store"
24		"example.com/tally/internal/subscriptions"
25		"example.com/tally/internal/webhooks"
26	)
27	
28	// Start is the fake clock's time when an Env is created.
29	var Start = time.Date(2026, time.January, 15, 10, 0, 0, 0, time.UTC)
30	
31	// Env is a running service and the fakes around it.
32	type Env struct {
33		T        testing.TB
34		Store    *store.Store
35		Clock    *clock.Fake
36		Gateway  *payments.Fake
37		Mail     *mail.Outbox
38		HTTP     *FakeHTTP // the organizations' webhook receivers
39		DNS      *FakeDNS
40		Webhooks *webhooks.Service
41		Payments *payments.Service
42		Subs     *subscriptions.Service
43		Server   *api.Server
44	
45		// Acme (team plan, America/New_York) and Globex (business plan, Europe/Berlin) each have an owner with an API key.
46		Acme, Globex Org
47	}
48	
49	// Org is an organization with its owner and the owner's API key.
50	type Org struct {
51		store.Org
52		Owner store.User
53		Key   string
54	}
55	
56	// New builds a service for a test.
57	func New(t testing.TB) *Env {
58		t.Helper()
59		e := &Env{T: t, Store: store.New(), Clock: clock.NewFake(Start), Gateway: &payments.Fake{}, Mail: &mail.Outbox{}, HTTP: &FakeHTTP{}, DNS: &FakeDNS{}}
60		e.DNS.Set("hooks.acme.example", "93.184.216.34")
61		e.DNS.Set("hooks.globex.example", "93.184.216.35")
62		e.Webhooks = webhooks.New(webhooks.Options{Store: e.Store, Clock: e.Clock, Doer: e.HTTP, Resolver: e.DNS})
63		e.Payments = &payments.Service{Store: e.Store, Gateway: e.Gateway, Clock: e.Clock, Publisher: e.Webhooks}
64		e.Subs = &subscriptions.Service{Store: e.Store, Payments: e.Payments, Clock: e.Clock, Publisher: e.Webhooks}
65		e.Server = api.New(e.Store, api.Options{Clock: e.Clock, Payments: e.Payments, Subscriptions: e.Subs, Webhooks: e.Webhooks, Mail: e.Mail})
66		e.Acme = e.NewOrg("Acme", store.OrgTeam, "America/New_York")
67		e.Globex = e.NewOrg("Globex", store.OrgBusiness, "Europe/Berlin")
68		return e
69	}
70	
71	// NewOrg adds an organization with an owner (owner@<name>.example) and the owner's API key.
72	func (e *Env) NewOrg(name string, plan store.OrgPlan, timeZone string) Org {
73		e.T.Helper()
74		now := e.Clock.Now()
75		o, err := e.Store.CreateOrg(name, plan, timeZone, 0, now)
76		if err != nil {
77			e.T.Fatalf("create org %s: %v", name, err)
78		}
79		u, err := e.Store.CreateUser("owner@"+strings.ToLower(name)+".example", name+" Owner", now)
80		if err != nil {
81			e.T.Fatalf("create owner of %s: %v", name, err)
82		}
83		if _, err := e.Store.AddMember(o.ID, u.ID, store.RoleOwner, now); err != nil {
84			e.T.Fatal(err)
85		}
86		k, err := e.Store.CreateAPIKey(o.ID, u.ID, "Owner key", now)
87		if err != nil {
88			e.T.Fatal(err)
89		}
90		return Org{Org: o, Owner: u, Key: k.Token}
91	}
92	
93	// AddMember adds a new user with this email address to org with a role, and returns them with an API key of theirs.
94	func (e *Env) AddMember(org Org, email string, role store.Role) (store.User, string) {
95		e.T.Helper()
96		now := e.Clock.Now()
97		u, ok := e.Store.UserByEmail(email)
98		if !ok {
99			var err error
100			if u, err = e.Store.CreateUser(email, strings.Split(email, "@")[0], now); err != nil {
101				e.T.Fatal(err)
102			}
103		}
104		if _, err := e.Store.AddMember(org.ID, u.ID, role, now); err != nil {
105			e.T.Fatal(err)
106		}
107		k, err := e.Store.CreateAPIKey(org.ID, u.ID, "Key of "+email, now)
108		if err != nil {
109			e.T.Fatal(err)
110		}
111		return u, k.Token
112	}
113	
114	// Response is the server's answer.
115	type Response struct {
116		Code   int
117		Header http.Header
118		Body   []byte
119	}
120	
121	// JSON decodes the body into v, failing the test when it cannot.
122	func (r *Response) JSON(t testing.TB, v any) {
123		t.Helper()
124		if err := json.Unmarshal(r.Body, v); err != nil {
125			t.Fatalf("response %d is not the JSON expected: %v\n%s", r.Code, err, r.Body)
126		}
127	}
128	
129	// Map decodes the body as a JSON object.
130	func (r *Response) Map(t testing.TB) map[string]any {
131		t.Helper()
132		var m map[string]any
133		r.JSON(t, &m)
134		return m
135	}
136	
137	// String is the status and body, for failure messages.
138	func (r *Response) String() string { return fmt.Sprintf("%d %s", r.Code, bytes.TrimSpace(r.Body)) }
139	
140	// Do sends a request to the server with key as its API key ("" for none). A body that is a string or []byte is sent as it
141	// is; any other non-nil body is sent as JSON.
142	func (e *Env) Do(method, path, key string, body any) *Response {
143		e.T.Helper()
144		return e.DoWith(method, path, key, body, nil)
145	}
146	
147	// DoWith is Do with extra request headers.
148	func (e *Env) DoWith(method, path, key string, body any, header http.Header) *Response {
149		e.T.Helper()
150		var rd io.Reader
151		switch b := body.(type) {
152		case nil:
153		case string:
154			rd = strings.NewReader(b)
155		case []byte:
156			rd = bytes.NewReader(b)
157		default:
158			raw, err := json.Marshal(b)
159			if err != nil {
160				e.T.Fatal(err)
161			}
162			rd = bytes.NewReader(raw)
163		}
164		req := httptest.NewRequest(method, path, rd)
165		if key != "" {
166			req.Header.Set("Authorization", "Bearer "+key)
167		}
168		for k, vs := range header {
169			for _, v := range vs {
170				req.Header.Add(k, v)
171			}
172		}
173		rec := httptest.NewRecorder()
174		e.Server.ServeHTTP(rec, req)
175		return &Response{Code: rec.Code, Header: rec.Header(), Body: rec.Body.Bytes()}
176	}
177	
178	// MustDo is Do that fails the test unless the answer has the status want, and decodes the body into out (when not nil).
179	func (e *Env) MustDo(want int, method, path, key string, body, out any) *Response {
180		e.T.Helper()
181		r := e.Do(method, path, key, body)
182		if r.Code != want {
183			e.T.Fatalf("%s %s: want %d, got %s", method, path, want, r)
184		}
185		if out != nil {
186			r.JSON(e.T, out)
187		}
188		return r
189	}
190	
191	// CreateCustomer creates a customer of org through the API.
192	func (e *Env) CreateCustomer(org Org, name, email string) store.Customer {
193		e.T.Helper()
194		var c store.Customer
195		e.MustDo(http.StatusCreated, "POST", "/v1/customers", org.Key, map[string]string{"name": name, "email": email}, &c)
196		return c
197	}
198	
199	// CreatePlan creates a monthly licensed plan of org through the API, priced in major units ("12.50").
200	func (e *Env) CreatePlan(org Org, name, currency, price string) store.Plan {
201		e.T.Helper()
202		var p store.Plan
203		e.MustDo(http.StatusCreated, "POST", "/v1/plans", org.Key, map[string]any{"name": name, "currency": currency, "price": price, "interval": "month"}, &p)
204		return p
205	}
206	
207	// ---- fakes
208	
209	// FakeHTTP plays the organizations' webhook receivers: it records every request and answers 200, or what Respond returns
210	// when it is set (a status code, or an error for a request that never got an answer).
211	type FakeHTTP struct {
212		// Respond, when set, answers each request. Set it before requests are made, or between them.
213		Respond func(r Request) (int, error)
214	
215		mu       sync.Mutex
216		requests []Request
217	}
218	
219	// Request is a request a FakeHTTP received.
220	type Request struct {
221		Method string
222		URL    string
223		Header http.Header
224		Body   []byte
225	}
226	
227	// Do implements webhooks.Doer.
228	func (f *FakeHTTP) Do(req *http.Request) (*http.Response, error) {
229		var body []byte
230		if req.Body != nil {
231			body, _ = io.ReadAll(req.Body)
232			req.Body.Close()
233		}
234		r := Request{Method: req.Method, URL: req.URL.String(), Header: req.Header.Clone(), Body: body}
235		f.mu.Lock()
236		f.requests = append(f.requests, r)
237		respond := f.Respond
238		f.mu.Unlock()
239		status := http.StatusOK
240		if respond != nil {
241			var err error
242			if status, err = respond(r); err != nil {
243				return nil, err
244			}
245		}
246		return &http.Response{StatusCode: status, Status: http.StatusText(status), Header: http.Header{}, Body: io.NopCloser(strings.NewReader("")), Request: req}, nil
247	}
248	
249	// Requests returns the requests received so far, oldest first.
250	func (f *FakeHTTP) Requests() []Request {
251		f.mu.Lock()
252		defer f.mu.Unlock()
253		return append([]Request(nil), f.requests...)
254	}
255	
256	// FakeDNS answers host lookups from the addresses Set gave it. Other hosts do not resolve.
257	type FakeDNS struct {
258		mu    sync.Mutex
259		hosts map[string][]string
260	}
261	
262	// Set makes host resolve to ips (none: the host does not resolve).
263	func (d *FakeDNS) Set(host string, ips ...string) {
264		d.mu.Lock()
265		defer d.mu.Unlock()
266		if d.hosts == nil {
267			d.hosts = map[string][]string{}
268		}
269		d.hosts[strings.ToLower(host)] = ips
270	}
271	
272	// LookupIPAddr implements webhooks.Resolver.
273	func (d *FakeDNS) LookupIPAddr(ctx context.Context, host string) ([]net.IPAddr, error) {
274		d.mu.Lock()
275		ips := d.hosts[strings.ToLower(host)]
276		d.mu.Unlock()
277		if len(ips) == 0 {
278			return nil, &net.DNSError{Err: "no such host", Name: host, IsNotFound: true}
279		}
280		out := make([]net.IPAddr, 0, len(ips))
281		for _, s := range ips {
282			ip := net.ParseIP(s)
283			if ip == nil {
284				return nil, fmt.Errorf("FakeDNS: %q is not an IP address", s)
285			}
286			out = append(out, net.IPAddr{IP: ip})
287		}
288		return out, nil
289	}
