func (s *Service) deliver(ctx context.Context, d store.Delivery) {
	status, errText := 0, ""
	ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
	e, eok := s.store.EventByID(d.EventID)
	switch {
	case !ok || !ep.Enabled:
		errText = "the endpoint is disabled or was deleted"
	case !eok:
		errText = "the event no longer exists"
	default:
		status, errText = s.send(ctx, ep, e)
	}
	now := s.clock.Now()
	_, _ = s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
		d.Attempts++
		d.LastAttemptAt = &now
		d.NextAttemptAt = nil
		d.ResponseStatus = status
		d.Error = errText
		if errText == "" {
			d.Status = store.DeliverySucceeded
		} else {
			d.Status = store.DeliveryFailed
		}
		return nil
	})
}

args.new_string:
func (s *Service) deliver(ctx context.Context, d store.Delivery) {
	ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
	e, eok := s.store.EventByID(d.EventID)
	switch {
	case !ok || !ep.Enabled:
		s.giveUp(d, "the endpoint is disabled or was deleted")
		return
	case !eok:
		s.giveUp(d, "the event no longer exists")
		return
	}
	status, errText := s.send(ctx, ep, e)
	now := s.clock.Now()
	gone := status == http.StatusGone
	d, _ = s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
		d.Attempts++
		d.LastAttemptAt = &now
		d.NextAttemptAt = nil
		d.ResponseStatus = status
		d.Error = errText
		switch {
		case errText == "":
			d.Status = store.DeliverySucceeded
		case gone || d.Attempts >= maxAttempts:
			d.Status = store.DeliveryFailed
		default:
			next := now.Add(retryDelays[d.Attempts-1])
			d.Status = store.DeliveryPending
			d.NextAttemptAt = &next
		}
		return nil
	})
	if gone {
		_, _ = s.store.UpdateWebhookEndpoint(ep.OrgID, ep.ID, func(ep *store.WebhookEndpoint) error {
			ep.Enabled = false
			ep.DisabledReason = "gone"
			return nil
		})
	}
	if d.Status == store.DeliveryFailed && errText != "" && !gone {
		s.notifyOwners(d.OrgID, ep)
	}
}

// giveUp fails a delivery for good without sending it. It is not an attempt.
func (s *Service) giveUp(d store.Delivery, reason string) {
	_, _ = s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
		d.NextAttemptAt = nil
		d.Status = store.DeliveryFailed
		d.Error = reason
		return nil
	})
}

// notifyOwners emails every owner of the organization that the endpoint is failing, unless it was emailed in the last day.
func (s *Service) notifyOwners(orgID string, ep store.WebhookEndpoint) {
	now := s.clock.Now()
	due := false
	_, err := s.store.UpdateWebhookEndpoint(orgID, ep.ID, func(ep *store.WebhookEndpoint) error {
		if ep.FailureMailAt != nil && now.Sub(*ep.FailureMailAt) < failureMailInterval {
			return nil
		}
		ep.FailureMailAt = &now
		due = true
		return nil
	})
	if err != nil || !due {
		return
	}
	for _, m := range s.store.Members(orgID) {
		u, ok := s.store.User(m.UserID)
		if m.Role != store.RoleOwner || !ok {
			continue
		}
		_ = s.mail.Send(context.Background(), mail.Message{
			To:      u.Email,
			Subject: "Webhook endpoint failing: " + ep.URL,
			Body: fmt.Sprintf("Tally could not deliver events to %s after %d attempts, so the deliveries failed for good.\n\n"+
				"Check the endpoint and its deliveries in the dashboard.\n", ep.URL, maxAttempts),
		})
	}
}

