// settle runs the endpoint's deliveries at each of their next attempt times, until none is pending.
func settle(t *testing.T, e *apitest.Env, orgID, endpointID string) {
	t.Helper()
	for range 20 {
		var next *time.Time
		for _, d := range e.Store.Deliveries(orgID, endpointID) {
			if d.Status == store.DeliveryPending && d.NextAttemptAt != nil && (next == nil || d.NextAttemptAt.Before(*next)) {
				next = d.NextAttemptAt
			}
		}
		if next == nil {
			return
		}
		e.Clock.Set(*next)
		if _, err := e.Webhooks.RunDue(context.Background()); err != nil {
			t.Fatal(err)
		}
	}
	t.Fatal("deliveries still pending")
}

func TestRetrySchedule(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/retry", Events: []string{"*"}, Secret: "whsec_r", Enabled: true}, e.Clock.Now())
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusBadGateway, nil }
	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
		t.Fatal(err)
	}

	// The waits after each failed attempt, counted from the failure.
	waits := []time.Duration{time.Minute, 5 * time.Minute, 30 * time.Minute, 2 * time.Hour, 8 * time.Hour, 24 * time.Hour}
	for i := 1; i <= 7; i++ {
		if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
			t.Fatalf("attempt %d: RunDue = %d, %v", i, n, err)
		}
		d := e.Store.Deliveries(e.Acme.ID, ep.ID)[0]
		if d.Attempts != i || d.ResponseStatus != http.StatusBadGateway || d.Error == "" || !d.LastAttemptAt.Equal(e.Clock.Now()) {
			t.Fatalf("after attempt %d: %+v", i, d)
		}
		if i < 7 {
			if d.Status != store.DeliveryPending || d.NextAttemptAt == nil || !d.NextAttemptAt.Equal(e.Clock.Now().Add(waits[i-1])) {
				t.Fatalf("after attempt %d: %+v, want pending at +%v", i, d, waits[i-1])
			}
			e.Clock.Advance(waits[i-1] - time.Second)
			if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
				t.Fatalf("attempt %d: retried a second early", i+1)
			}
			e.Clock.Advance(time.Second)
		} else if d.Status != store.DeliveryFailed || d.NextAttemptAt != nil {
			t.Fatalf("after the 7th attempt: %+v, want failed for good", d)
		}
	}
	if n, _ := e.Webhooks.RunDue(ctx); n != 0 || len(e.HTTP.Requests()) != 7 {
		t.Fatalf("RunDue = %d after the last attempt; %d requests in all", n, len(e.HTTP.Requests()))
	}
}

func TestRetryThenSucceed(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/flaky", Events: []string{"*"}, Secret: "whsec_f", Enabled: true}, e.Clock.Now())
	fails := 2
	e.HTTP.Respond = func(apitest.Request) (int, error) {
		if fails > 0 {
			fails--
			return 0, errors.New("connection refused")
		}
		return http.StatusNoContent, nil
	}
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_1"})
	settle(t, e, e.Acme.ID, ep.ID)
	ds := e.Store.Deliveries(e.Acme.ID, ep.ID)
	if len(ds) != 1 || ds[0].Status != store.DeliverySucceeded || ds[0].Attempts != 3 || ds[0].Error != "" || ds[0].NextAttemptAt != nil {
		t.Fatalf("deliveries = %+v", ds)
	}
	if n := len(e.HTTP.Requests()); n != 3 {
		t.Fatalf("%d requests, want 3", n)
	}
}

