	for _, d := range e.Store.Deliveries(e.Acme.ID, ep.ID) {
		if d.Status != store.DeliveryFailed || d.NextAttemptAt != nil {
			t.Fatalf("delivery = %+v, want failed for good", d)
		}
	}
	if n := len(e.Mail.Messages()); n != 0 {
		t.Fatalf("%d emails for a 410, want none", n)
	}
}

func TestFailureEmailOncePerDay(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/down", Events: []string{"*"}, Secret: "whsec_e", Enabled: true}, e.Clock.Now())
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusInternalServerError, nil }
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_4"})
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "customer.updated", map[string]string{"id": "cus_4"})
	settle(t, e, e.Acme.ID, ep.ID)

	// Both deliveries failed for good; the owner is emailed once.
	msgs := e.Mail.Messages()
	want := "Webhook endpoint failing: https://hooks.acme.example/down"
	if len(msgs) != 1 || msgs[0].To != "owner@acme.example" || msgs[0].Subject != want {
		t.Fatalf("emails = %+v", msgs)
	}

	// Another failure within a day is not emailed again; one a day later is.
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_2"})
	settle(t, e, e.Acme.ID, ep.ID)
	if n := len(e.Mail.Messages()); n != 1 {
		t.Fatalf("%d emails within a day, want 1", n)
	}
	e.Clock.Advance(24 * time.Hour)
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.voided", map[string]string{"invoice_id": "in_3"})
	settle(t, e, e.Acme.ID, ep.ID)
	if n := len(e.Mail.Messages()); n != 2 {
		t.Fatalf("%d emails a day later, want 2", n)
	}
}

