136	// Publish records an event and queues a delivery of it to every enabled endpoint of the organization that subscribes to its
137	// type. The deliveries are sent by RunDue.
138	func (s *Service) Publish(ctx context.Context, orgID, eventType string, data any) error {
139		raw, err := json.Marshal(data)
140		if err != nil {
141			return err
142		}
143		now := s.clock.Now()
144		e, err := s.store.AddEvent(orgID, eventType, raw, now)
145		if err != nil {
146			return err
147		}
148		for _, ep := range s.store.WebhookEndpoints(orgID) {
149			if !ep.Enabled || !(slices.Contains(ep.Events, "*") || slices.Contains(ep.Events, eventType)) {
150				continue
151			}
152			next := now
153			if _, err := s.store.CreateDelivery(store.Delivery{OrgID: orgID, EndpointID: ep.ID, EventID: e.ID, NextAttemptAt: &next}, now); err != nil {
154				return err
155			}
156		}
157		return nil
158	}
